// ============================================================================
// Apply R/P (CPU, interleaved multi-variable layout)
// ============================================================================

void PrismRPOperatorTable::ApplyRestrict(int p_hi,
                                          const double* u_hi, int n_sp_hi,
                                          double* u_lo, int& n_sp_lo,
                                          int nv) const {
    assert(built_);
    const DenseMatrix& R = restrict_full_[p_hi];
    assert(R.cols == n_sp_hi);
    n_sp_lo = R.rows;

    std::memset(u_lo, 0, static_cast<size_t>(n_sp_lo * nv) * sizeof(double));

    for (int i = 0; i < n_sp_lo; ++i)
        for (int j = 0; j < n_sp_hi; ++j) {
            double a = R(i, j);
            for (int k = 0; k < nv; ++k)
                u_lo[i * nv + k] += a * u_hi[j * nv + k];
        }
}

void PrismRPOperatorTable::ApplyProlong(int p_lo,
                                         const double* u_lo, int n_sp_lo,
                                         double* u_hi, int& n_sp_hi,
                                         int nv) const {
    assert(built_);
    const DenseMatrix& P = prolong_full_[p_lo];
    assert(P.cols == n_sp_lo);
    n_sp_hi = P.rows;

    std::memset(u_hi, 0, static_cast<size_t>(n_sp_hi * nv) * sizeof(double));

    for (int i = 0; i < n_sp_hi; ++i)
        for (int j = 0; j < n_sp_lo; ++j) {
            double a = P(i, j);
            for (int k = 0; k < nv; ++k)
                u_hi[i * nv + k] += a * u_lo[j * nv + k];
        }
}

// ============================================================================
// Verify R·P = I
// ============================================================================

double PrismRPOperatorTable::VerifyRP() const {
    double max_dev = 0.0;
    for (int p = 1; p <= max_order_; ++p) {
        double dev = VerifyRP(p);
        if (dev > max_dev) max_dev = dev;
    }
    return max_dev;
}

double PrismRPOperatorTable::VerifyRP(int p) const {
    const DenseMatrix& R = restrict_full_[p];    // maps p → p-1
    const DenseMatrix& P = prolong_full_[p - 1]; // maps p-1 → p
    int n = R.rows;
    assert(R.cols == P.rows);
    assert(P.cols == n);

    double max_dev = 0.0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            double val = 0.0;
            for (int k = 0; k < R.cols; ++k)
                val += R(i, k) * P(k, j);
            double expected = (i == j) ? 1.0 : 0.0;
            double dev = std::abs(val - expected);
            if (dev > max_dev) max_dev = dev;
        }
    }
    return max_dev;
}

// ============================================================================
// Print summary
// ============================================================================

void PrismRPOperatorTable::PrintSummary() const {
    std::cout << "=== PrismRPOperatorTable Summary (extracted from hpMusic) ===\n"
              << "  max_order = " << max_order_ << "\n\n";

    for (int p = 1; p <= max_order_; ++p) {
        const auto& Rf = restrict_full_[p];
        std::cout << "  Restrict p=" << p << " -> p=" << (p - 1)
                  << "  Full: " << Rf.rows << "x" << Rf.cols << "\n";
    }
    for (int p = 0; p < max_order_; ++p) {
        const auto& Pf = prolong_full_[p];
        std::cout << "  Prolong  p=" << p << " -> p=" << (p + 1)
                  << "  Full: " << Pf.rows << "x" << Pf.cols << "\n";
    }

    // Verify R·P = I at each level
    for (int p = 1; p <= max_order_; ++p) {
        double err = VerifyRP(p);
        std::cout << "  R*P = I  p=" << p << "  max deviation: "
                  << std::scientific << err << "\n";
    }
    std::cout << "====================================\n";
}

// ============================================================================
// Binary serialization
// ============================================================================

void PrismRPOperatorTable::SaveBinary(const std::string& path) const {
    std::ofstream ofs(path, std::ios::binary);
    if (!ofs) throw std::runtime_error("Cannot open " + path + " for writing");

    char magic[8] = "PRSMOP2";   // version 2: extracted (no sub-operators)
    ofs.write(magic, 8);
    int32_t maxp = max_order_;
    ofs.write(reinterpret_cast<const char*>(&maxp), 4);

    auto writeMatrix = [&](const DenseMatrix& M) {
        int32_t r = M.rows, c = M.cols;
        ofs.write(reinterpret_cast<const char*>(&r), 4);
        ofs.write(reinterpret_cast<const char*>(&c), 4);
        ofs.write(reinterpret_cast<const char*>(M.data.data()),
                  static_cast<std::streamsize>(M.data.size() * sizeof(double)));
    };

    for (int p = 0; p < maxp; ++p) writeMatrix(prolong_full_[p]);
    for (int p = 1; p <= maxp; ++p) writeMatrix(restrict_full_[p]);
}

bool PrismRPOperatorTable::LoadBinary(const std::string& path) {
    std::ifstream ifs(path, std::ios::binary);
    if (!ifs) return false;

    char magic[8];
    ifs.read(magic, 8);
    if (std::string(magic, 7) != "PRSMOP2") return false;

    int32_t maxp;
    ifs.read(reinterpret_cast<char*>(&maxp), 4);
    max_order_ = maxp;

    auto readMatrix = [&](DenseMatrix& M) {
        int32_t r, c;
        ifs.read(reinterpret_cast<char*>(&r), 4);
        ifs.read(reinterpret_cast<char*>(&c), 4);
        M = DenseMatrix(r, c);
        ifs.read(reinterpret_cast<char*>(M.data.data()),
                 static_cast<std::streamsize>(M.data.size() * sizeof(double)));
    };

    for (int p = 0; p < maxp; ++p) readMatrix(prolong_full_[p]);
    for (int p = 1; p <= maxp; ++p) readMatrix(restrict_full_[p]);

    built_ = true;
    return true;
}

